pub const VERSION: i64 = 1;
pub const SCHEMA: &str = r#"
CREATE TABLE archives(id TEXT PRIMARY KEY, writer TEXT NOT NULL, sequence INTEGER NOT NULL DEFAULT 0);
CREATE TABLE blobs(digest TEXT PRIMARY KEY, size INTEGER NOT NULL CHECK(size>=0), metadata TEXT, extractor TEXT);
CREATE TABLE metadata_cache(digest TEXT NOT NULL,extractor TEXT NOT NULL,metadata TEXT NOT NULL,PRIMARY KEY(digest,extractor));
CREATE TABLE groups(id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0, primary_raw TEXT);
CREATE TABLE aliases(alias TEXT PRIMARY KEY REFERENCES groups(id), canonical TEXT NOT NULL REFERENCES groups(id), CHECK(alias<>canonical));
CREATE TABLE members(archive TEXT NOT NULL, path TEXT NOT NULL, group_id TEXT NOT NULL REFERENCES groups(id), digest TEXT NOT NULL REFERENCES blobs(digest), role TEXT NOT NULL, PRIMARY KEY(archive,path));
CREATE TABLE associations(id TEXT PRIMARY KEY, evidence TEXT NOT NULL);
CREATE TABLE sources(incarnation TEXT NOT NULL,path TEXT NOT NULL,size INTEGER NOT NULL,mtime TEXT NOT NULL,digest TEXT NOT NULL REFERENCES blobs(digest),PRIMARY KEY(incarnation,path));
CREATE TABLE placements(id TEXT PRIMARY KEY,group_id TEXT NOT NULL,path TEXT NOT NULL,digest TEXT NOT NULL,local_ready INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,UNIQUE(path,group_id));
CREATE TABLE sidecars(id TEXT PRIMARY KEY,group_id TEXT REFERENCES groups(id),path TEXT NOT NULL,owner TEXT NOT NULL,protected INTEGER NOT NULL DEFAULT 1);
CREATE TABLE versions(id TEXT PRIMARY KEY,sidecar TEXT NOT NULL REFERENCES sidecars(id),body TEXT NOT NULL,origin TEXT NOT NULL,operation TEXT NOT NULL UNIQUE);
CREATE TABLE version_parents(version TEXT NOT NULL REFERENCES versions(id),parent TEXT NOT NULL REFERENCES versions(id),PRIMARY KEY(version,parent),CHECK(version<>parent));
CREATE TABLE heads(sidecar TEXT NOT NULL REFERENCES sidecars(id),version TEXT NOT NULL REFERENCES versions(id),PRIMARY KEY(sidecar,version));
CREATE TABLE projections(sidecar TEXT PRIMARY KEY REFERENCES sidecars(id),committed TEXT,applied TEXT,observed TEXT,pending INTEGER NOT NULL DEFAULT 1);
CREATE TABLE commits(id TEXT PRIMARY KEY,envelope BLOB NOT NULL,applied INTEGER NOT NULL DEFAULT 0,reason TEXT);
CREATE TABLE dependencies(commit_id TEXT NOT NULL REFERENCES commits(id),dependency TEXT NOT NULL,PRIMARY KEY(commit_id,dependency));
CREATE TABLE jobs(id TEXT PRIMARY KEY,operation TEXT NOT NULL UNIQUE,request TEXT NOT NULL,state TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 0,local_ready INTEGER NOT NULL DEFAULT 0,archive_committed INTEGER NOT NULL DEFAULT 0,reason TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0);
CREATE TABLE attempts(job TEXT NOT NULL REFERENCES jobs(id),generation INTEGER NOT NULL,state TEXT NOT NULL,receipt TEXT,PRIMARY KEY(job,generation));
CREATE TABLE reservations(id TEXT PRIMARY KEY,job TEXT NOT NULL REFERENCES jobs(id),filesystem TEXT NOT NULL,remaining INTEGER NOT NULL CHECK(remaining>=0));
CREATE TABLE residency(group_id TEXT PRIMARY KEY REFERENCES groups(id),pin INTEGER NOT NULL DEFAULT 0,ready_revision INTEGER,metadata_current INTEGER NOT NULL DEFAULT 0,protected INTEGER NOT NULL DEFAULT 1,conflict INTEGER NOT NULL DEFAULT 0,last_activity INTEGER NOT NULL DEFAULT 0);
CREATE TABLE snapshots(digest TEXT PRIMARY KEY,path TEXT NOT NULL,size INTEGER NOT NULL,archived INTEGER NOT NULL DEFAULT 0,refs INTEGER NOT NULL DEFAULT 1,cleanup_intent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE rating_observations(id TEXT PRIMARY KEY,group_id TEXT NOT NULL,local TEXT,remote TEXT,common TEXT,applied TEXT,pending TEXT);
CREATE TABLE rating_intents(id TEXT PRIMARY KEY,operation TEXT NOT NULL UNIQUE,group_id TEXT NOT NULL,server TEXT NOT NULL,asset TEXT NOT NULL,jpeg TEXT NOT NULL,expected TEXT NOT NULL,desired INTEGER NOT NULL,state TEXT NOT NULL);
CREATE TABLE pin_targets(job TEXT PRIMARY KEY REFERENCES jobs(id),group_id TEXT NOT NULL REFERENCES groups(id));
CREATE TABLE pin_batches(operation TEXT NOT NULL,asset TEXT NOT NULL,child_operation TEXT NOT NULL UNIQUE,PRIMARY KEY(operation,asset));
CREATE TABLE mappings(server TEXT NOT NULL,asset TEXT NOT NULL,library TEXT,path TEXT NOT NULL,digest TEXT,group_id TEXT NOT NULL REFERENCES groups(id),stale INTEGER NOT NULL DEFAULT 0,remote_checksum TEXT NOT NULL DEFAULT '',external_path TEXT NOT NULL DEFAULT '',PRIMARY KEY(server,asset));
CREATE TABLE conflicts(id TEXT PRIMARY KEY,kind TEXT NOT NULL,group_id TEXT,revision INTEGER NOT NULL DEFAULT 0,details TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE capabilities(id TEXT PRIMARY KEY,report TEXT NOT NULL);
CREATE TABLE blocked_records(id TEXT PRIMARY KEY,reason TEXT NOT NULL);
CREATE TABLE observations(path TEXT PRIMARY KEY,digest TEXT,size INTEGER,absent_since INTEGER,readable INTEGER NOT NULL DEFAULT 1,tool_digest TEXT);
PRAGMA user_version=1;
"#;
pub const IMPORT_SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS import_items(id TEXT PRIMARY KEY,parent TEXT NOT NULL REFERENCES jobs(id),source_root TEXT NOT NULL,source_path TEXT NOT NULL,digest TEXT NOT NULL,size INTEGER NOT NULL,role TEXT NOT NULL,group_id TEXT,destination TEXT NOT NULL,state TEXT NOT NULL,local_ready INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,warning INTEGER NOT NULL DEFAULT 0,UNIQUE(parent,source_path,digest));
CREATE TABLE IF NOT EXISTS upload_plans(item TEXT PRIMARY KEY,plan TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS writer_sequences(writer TEXT PRIMARY KEY,sequence INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS import_stats(job TEXT PRIMARY KEY REFERENCES jobs(id),selected INTEGER NOT NULL DEFAULT 0,recognized INTEGER NOT NULL DEFAULT 0,exif_calls INTEGER NOT NULL DEFAULT 0,transfer_bytes INTEGER NOT NULL DEFAULT 0,hash_bytes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS group_facts(context TEXT NOT NULL,stem TEXT NOT NULL,camera TEXT NOT NULL,capture TEXT NOT NULL,group_id TEXT NOT NULL REFERENCES groups(id),PRIMARY KEY(context,stem,camera,capture));
"#;
pub const EDIT_SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS local_heads(sidecar TEXT PRIMARY KEY REFERENCES sidecars(id),version TEXT NOT NULL REFERENCES versions(id),dirty INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS snapshot_intents(operation TEXT PRIMARY KEY,version TEXT NOT NULL UNIQUE,sidecar TEXT NOT NULL,parents TEXT NOT NULL,body TEXT NOT NULL,origin TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pending_resolutions(conflict TEXT PRIMARY KEY,version TEXT NOT NULL,expected_heads TEXT NOT NULL);
"#;
pub const RATING_SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS rating_baselines(group_id TEXT PRIMARY KEY REFERENCES groups(id),common TEXT NOT NULL,applied_local TEXT NOT NULL,pending INTEGER,pending_version TEXT,source_version TEXT,remote_observation TEXT);
CREATE TABLE IF NOT EXISTS rating_remote_state(server TEXT NOT NULL,asset TEXT NOT NULL,value TEXT NOT NULL,observation TEXT NOT NULL,PRIMARY KEY(server,asset));
CREATE TABLE IF NOT EXISTS rating_operations(key TEXT PRIMARY KEY,operation TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pending_shared_records(operation TEXT PRIMARY KEY,records TEXT NOT NULL,committed INTEGER NOT NULL DEFAULT 0);
"#;
pub const RATING_AUTHORITY_SCHEMA: &str = "CREATE TABLE rating_authorities(group_id TEXT PRIMARY KEY REFERENCES groups(id),server TEXT NOT NULL,asset TEXT NOT NULL,FOREIGN KEY(server,asset) REFERENCES mappings(server,asset));";
